import json, requests

webhook = "https://open.feishu.cn/open-apis/bot/v2/hook/39ace5b8-ddf6-4ccf-8912-2c2681c618a4"

card = {
    "msg_type": "interactive",
    "card": {
        "header": {
            "title": {
                "tag": "plain_text",
                "content": "✅ 澳洲冰箱新品监控日报 - 2026-07-09"
            },
            "template": "blue"
        },
        "elements": [
            {
                "tag": "div",
                "text": {
                    "tag": "lark_md",
                    "content": "**今日 5 品牌均无新品上架或状态变更。**\n\n---\n\n**🔵 海信 Hisense AU**\n• 53 款产品在线，2026 年发布仍为 5 款\n• 无新增型号，无状态变更\n\n**🔵 美的 Midea AU**\n• 官网 JS 渲染，产品列表正常（无新增）\n• 3 款 Coming Soon 仍无变化\n\n**🔵 三星 Samsung AU**\n• 搜索无 AU 市场冰箱新品公告\n\n**🔵 LG AU**\n• 搜索无 AU 市场冰箱新品\n\n**🔵 西屋 Westinghouse AU**\n• 页面抓取超时，搜索无新品发现"
                }
            },
            {
                "tag": "hr"
            },
            {
                "tag": "note",
                "elements": [
                    {
                        "tag": "plain_text",
                        "content": "由 Incaier Agent 自动监控 | 下次汇总：明天下午 3:07"
                    }
                ]
            }
        ]
    }
}

resp = requests.post(webhook, json=card, timeout=15)
result = {"status_code": resp.status_code, "body": resp.json()}
with open(sys.argv[-1], 'w', encoding='utf-8') as f:
    json.dump(result, f, ensure_ascii=False, indent=2)

